class Player:
    def __init__(self, name):
        self.name = name
        self.hp = 100

    def take_damage(self, dmg):
        self.hp -= dmg
        if self.hp <= 0:
            print(f'{self.name} пал в бою 💀')
        else:
            print(f'{self.name}: осталось {self.hp} HP')

hero = Player('Азиз')
hero.take_damage(30)
hero.take_damage(80)

class Animal:
    def __init__(self, name):
        self.name = name

    def eat(self):
        print(f'{self.name} ест')

class Cat(Animal):  # Cat наследует Animal
    def meow(self):
        print(f'{self.name}: мяу!')

barsik = Cat('Барсик')
barsik.eat()   # метод родителя работает!
barsik.meow()  # и свой тоже

class Enemy:
    def __init__(self, hp):
        self.hp = hp

    def info(self):
        print(f'Враг: {self.hp} HP')

class Boss(Enemy):
    def __init__(self, hp, phase):
        super().__init__(hp)   # вызвали __init__ родителя
        self.phase = phase

    def info(self):           # переопределили
        print(f'БОСС: {self.hp} HP, фаза {self.phase} 👹')

Enemy(50).info()
Boss(500, 2).info()

